function processFocus(id){const o=model.objects.get(id);if(['journey','task','event','gateway'].includes(o?.type))return id;const linked=model.relationships.find(e=>e.type==='implementedBy'&&e.to===id&&model.objects.get(e.from)?.type==='journey');return linked?.from||(model.objects.has('JRN-001')?'JRN-001':view?.objects.find(n=>n.type==='journey')?.id||null);}
function implementationFocus(id){const o=model.objects.get(id);if(o?.type==='responsibility')return id;const direct=model.relationships.find(e=>e.type==='implementedBy'&&e.from===id);if(direct)return direct.to;const requirement=model.relationships.find(e=>e.type==='requires'&&e.from===id)?.to;return model.objects.get(requirement)?.attributes.modelRef||id;}
function scenarioEdges(){const scenario=processPaths(currentProject()).find(p=>p.id===processScenario),ids=scenario?.ids||[];return ids.slice(1).map((to,i)=>view.relationships.find(e=>e.from===ids[i]&&e.to===to)).filter(Boolean);}
function processControls(){const paths=processPaths(currentProject()),active=paths.find(p=>p.id===processScenario),claims=currentProject()?.processModel?.claims||[],conflicts=processConflicts(currentProject()||{});
 return `<section class="am-process-guide" aria-label="Process journey"><div class="am-process-intro"><div><small>Process · same architecture, same object identities</small><strong>${paths.length?'How does this payment reach its outcome?':'Follow the recorded journey and review its conditional routes'}</strong><p>Trace a path, select a step for its responsibility and evidence, then reveal its application implementation. Reference paths are illustrative.</p></div><div class="am-process-actions">${B('new','Add process object',state.baselineId?'disabled':'')}${B('process-connect','Add condition',state.baselineId?'disabled':'')}</div></div>${paths.length?`<nav class="am-process-scenarios" aria-label="Choose a payment outcome">${paths.map(p=>B('process-scenario',esc(p.title),`data-id="${p.id}" aria-pressed="${p.id===processScenario}"`)).join('')}</nav><ol class="am-process-steps">${active.ids.map((id,i)=>{const o=model.objects.get(id);return `<li><button type="button" data-am="process-select" data-id="${esc(id)}" aria-current="${id===state.selectedId?'step':'false'}"><span>${i+1}</span><strong>${esc(o?.title||id)}</strong><small>${esc(o?.type==='gateway'?'Decision':o?.type==='event'?'Outcome':o?.owner||'Journey step')}</small></button></li>`;}).join('')}</ol>`:''}<p class="am-process-note">${claims.length} source claim${claims.length===1?'':'s'} recorded · ${conflicts.length} unreconciled topic${conflicts.length===1?'':'s'} requiring review. A staged change never approves a claim automatically.</p></section>`;
}
function processDetails(o){if(!['journey','task','gateway','event','account','claim'].includes(o.type))return '';
 const p=currentProject(),questions=processSourceQuestions(p,o.id),claims=(p.processModel?.claims||[]).filter(c=>c.subjectId===o.id),conflicting=processConflicts(p).filter(g=>g.some(c=>c.subjectId===o.id)),reqIds=o.type==='journey'?p.relationships?.filter(e=>e.from===o.id&&e.kind==='requires').map(e=>e.to)||[]:o.attributes.requirementIds||[];
 return `<section class="am-process-details"><h3>Process question</h3><p>${esc(o.type==='gateway'?'Which condition selects each path, and who decides?':o.type==='event'?'What evidence establishes this outcome?':'Which requirement authorises this step, and what is its next permitted outcome?')}</p>${reqIds.length?`<h3>Linked requirements and implementation</h3>${reqIds.map(id=>{const r=p.artefacts?.find(a=>a.id===id),target=model.objects.get(r?.modelRef);return `<p><a href="${esc(projectURL('/?chapter=1&tab=work&artefact='+encodeURIComponent(id)))}">${esc(id+' · '+(r?.title||'Requirement'))}</a>${target?`<br><button type="button" data-am="implementation" data-id="${esc(o.id)}">${esc(target.title)} · reveal implementation →</button>`:''}</p>`;}).join('')}`:''}${questions.map(q=>`<div class="am-source-question"><strong>${esc(q.topic)} · ${esc(q.status)}</strong><p>${esc(q.question)}</p><small>${q.sources.map(esc).join(' · ')}</small></div>`).join('')}<h3>Source claims · ${claims.length}</h3>${claims.map(c=>`<p><b>${esc(c.topic)}</b>: ${esc(c.statement)}<br><small>${esc(c.source)} · ${esc(c.sourceLocator)} · Needs review</small></p>`).join('')||'<p>No specific claim is recorded for this object. Its reference route remains illustrative.</p>'}${conflicting.length?'<p class="am-conflict">Statements differ. Inspect the sources and their abstraction levels before choosing a route.</p>':''}${B('process-claim','Record a source claim','data-id="'+esc(o.id)+'"'+(state.baselineId?' disabled':''))}</section>`;
}
function edgeClaims(edge){if(edge.type!=='sequence')return '';const claims=(currentProject()?.processModel?.claims||[]).filter(c=>c.subjectId===edge.id);
 return `<section class="am-process-details"><h3>Evidence for this condition</h3>${claims.map(c=>`<p><b>${esc(c.topic)}</b>: ${esc(c.statement)}<br><small>${esc(c.source)} · ${esc(c.sourceLocator)} · Needs review</small></p>`).join('')||'<p>No source claim has been reviewed for this path. Its route remains a working or illustrative condition.</p>'}${B('process-claim','Record a source claim','data-id="'+esc(edge.id)+'"'+(state.baselineId?' disabled':''))}</section>`;
}
function hideCursor(){cursorId=null;const tip=root?.querySelector('#am-cursor-tip');if(tip)tip.hidden=true;root?.querySelectorAll('[aria-describedby="am-cursor-tip"]').forEach(b=>b.removeAttribute('aria-describedby'));}
function placeCursor(tip,x,y){const width=tip.offsetWidth||280,height=tip.offsetHeight||150;tip.style.left=Math.max(12,Math.min(window.innerWidth-width-12,x+16))+'px';tip.style.top=Math.max(12,Math.min(window.innerHeight-height-12,y+16))+'px';}
function cursorQuestion(o,gap,edge,other){if(state.concern==='process')return `For ${o.title} (${o.id}), explain the conditions selecting its outgoing paths, requirements and implementation responsibilities, recovery on an unknown outcome, source claims and open reconciliation questions. Label every illustrative or unreviewed statement and identify evidence needed before acceptance.`;if(caseOpen&&caseFile?.caseIds.has(o.id))return `For ${o.title} in the uncertain settlement investigation, follow its recorded connections to ${caseFile.contract?.title||'the external contract'}, ${caseFile.driver?.title||'the recovery scenario'} and the draft decision. Compare enquiry before replay with immediate retry; identify actual objects affected, the open provider guarantees, ownership and evidence. Label all illustrative assertions and do not assume a timeout means failure.`;const task=gap?`${gap.detail}. Compare ways to close this mapping and their obligations.`:edge?`Explain the ${edge.label} relationship to ${other?.title||'the connected object'}, including failure and ownership responsibilities.`:'Identify its role, dependencies and unanswered design questions.';return `For ${o.title} (${OBJECT_TYPES[o.type].label}), ${task} Ground the answer in this project, label unconfirmed assumptions, and show which model objects or evidence need review.`;}
function showCursor(button,event){if(!cursorOn||journeyOption||!button)return;const node=button.closest('[data-object-id]'),o=model.objects.get(node?.dataset.objectId),tip=root?.querySelector('#am-cursor-tip');if(!o||!tip)return;
 const edges=view.relationships.filter(e=>e.from===o.id||e.to===o.id),edge=edges[0],other=edge&&model.objects.get(edge.from===o.id?edge.to:edge.from),gap=view.gaps.find(g=>g.id===o.id),reason=objectReasoning(currentProject(),journey,o.id,o.record);
 const question=caseFile?.caseIds.has(o.id)?(o.type==='contract'?'What happens after a missing response, and who can safely replay?':'Follow this object into the unresolved payment outcome and compare recovery choices.'):state.concern==='process'?(o.type==='gateway'?'Which evidence decides this branch?':o.id==='JRN-004'?'What settles an uncertain payment, and who owns the switch boundary?':'What happens next, who owns it, and what supports it?'):gap?'What mapping or evidence would resolve this gap?':edge?'What happens at this '+edge.label+' relationship?':'What depends on this object, and how is that justified?';
 tip.innerHTML=`<small>${esc(OBJECT_TYPES[o.type].label)} · ${esc(o.status)}</small><strong>${esc(o.title)}</strong><p>${gap?esc(gap.detail):edge?esc(edge.label+' · '+(other?.title||'Unresolved object')):'No connection shown in this chapter view.'}</p>${reason?.requirement?`<p>Linked question: ${esc(reason.requirement.title)}</p>`:''}<em>${esc(question)}</em><div class="am-cursor-actions">${caseFile?.caseIds.has(o.id)?B('case-start','Trace the uncertainty'):''}${B('ask-sol','Ask Sol')}</div>`;
 tip.hidden=false;cursorId=o.id;button.setAttribute('aria-describedby','am-cursor-tip');const rect=button.getBoundingClientRect();placeCursor(tip,event?.clientX||rect.left+rect.width/2,event?.clientY||rect.top+rect.height/2);
}
function cursorOver(e){if(e.pointerType==='touch')return;const button=e.target.closest?.('.am-node-main');if(button&&button.closest('.am-explorer')===root&&button.closest('[data-object-id]')?.dataset.objectId!==cursorId)showCursor(button,e);}
function cursorOut(e){const button=e.target.closest?.('.am-node-main');if(button&&!button.contains(e.relatedTarget)&&!e.relatedTarget?.closest?.('#am-cursor-tip'))hideCursor();if(e.target.closest?.('#am-cursor-tip')&&!e.relatedTarget?.closest?.('#am-cursor-tip,.am-node-main'))hideCursor();}
