// Give the canvas all the height left below the model controls. Re-run whenever the
// surrounding chrome changes size (panels opening, the toolbar wrapping, the guide collapsing).
function fitViewport(){
 const vp=root?.querySelector('.am-viewport');if(!vp)return;
 const footH=root.querySelector('.am-bottom')?.offsetHeight||48,pageFootH=document.body.classList.contains('am-focus')?8:(document.querySelector('.footer')?.offsetHeight||27)+12;
 const next=Math.max(window.innerWidth<700?380:300,Math.round(window.innerHeight-vp.getBoundingClientRect().top-window.scrollY*0-footH-pageFootH-(root.querySelector('.am-sequence')?.offsetHeight||0)))+'px';
 if(root.style.getPropertyValue('--am-view-height')!==next)root.style.setProperty('--am-view-height',next);
}
let fitObserver=null;
function observeChrome(){
 if(!('ResizeObserver' in window))return;
 fitObserver?.disconnect();
 fitObserver=new ResizeObserver(()=>requestAnimationFrame(fitViewport));
 for(const el of root.querySelectorAll('.am-toolbar,.am-chapter-band,.am-case,.am-bottom'))fitObserver.observe(el);
 fitObserver.observe(root);
}
window.addEventListener('resize',()=>{if(root?.isConnected)fitViewport();});
