 if(a==='smart-arrange'){try{capture();const pins=heldPositions(),reflowed=smartArrangeArchitecture(model,view,state,viewWidth(),pins);arrangements.set(viewKey(),pins);remember();render();notify('Reflowed '+Object.keys(reflowed).length+' objects around '+Object.keys(pins).length+' held placements. Definitions are unchanged.');}catch(error){notify(error.message);}return;}
 if(a==='release-placement'){capture();const positions=heldPositions();delete positions[id];arrangements.set(viewKey(),positions);remember();render();notify('This object can move with the next arrangement.');return;}
 if(a==='journey-option'){journeyOption=el.dataset.option;detailOpen=false;render();return;}
 if(a==='origin'){const linked=journey?.task.applied?.records?.find(r=>r.slot==='processor responsibility');detailOpen=true;return navigate({selectedId:linked?.id||journey.requirement.id,scopeId:linked?.id||model.root,concern:linked?'realization':'rationale'});}
