 if(a==='journey-review'){const selectedOption=el.dataset.option||journeyOption,chosen=selectedOption?journey?.options.find(x=>x.option.id===selectedOption&&x.alternative):journey?.options.find(x=>x.alternative);if(!chosen)return notify('Develop this model proposal in Mind Factory first.');journeyOption=null;render();window.aiwInterfaceImpact?.loadAlternative(chosen.alternative.id);return;}
 if(a==='journey-sdd'){location.href=projectURL('/?chapter=11&tab=output');return;}
